import{_ as r,a0 as p,w as e,s as I,ao as u,I as i,x as t,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"Linux 下易用的光盘镜像管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下易用的光盘镜像管理工具 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下易用的光盘镜像管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下易用的光盘镜像管理工具 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141027 Handy Disk Image Tools","title":"Linux 下易用的光盘镜像管理工具","tag":"201411","desc":""},"relativePath":"201411/20141027 Handy Disk Image Tools.md","filePath":"[post].md"}'),D={name:"201411/20141027 Handy Disk Image Tools.md"};function S(m,l,d,T,a,f){const n=p("Link");return e(),I("div",null,[l[36]||(l[36]=u('<h1 id="linux-下易用的光盘镜像管理工具" tabindex="-1">Linux 下易用的光盘镜像管理工具 <a class="header-anchor" href="#linux-下易用的光盘镜像管理工具" aria-label="Permalink to “Linux 下易用的光盘镜像管理工具”">​</a></h1><p>磁盘镜像包括了整个磁盘卷的文件或者是全部的存储设备的数据，比如说硬盘，光盘（DVD,CD,蓝光光碟），磁带机，USB闪存，软盘。一个完整的磁盘镜像应该包含与原来的存储设备上一样完整、准确，包括数据和结构信息。</p><p>磁盘镜像文件格式可以是采用开放的标准，像ISO格式的光盘镜像，或者是专有的软件应用程序的特定格式。&quot;ISO&quot;这个名字来源于用CD存储的ISO 9660文件系统。但是，当用户转向Linux的时候，经常遇到这样的问题，需要把专有的的镜像格式转换为开放的格式。</p><p>磁盘镜像有很多不同的用处，像烧录光盘，系统备份，数据恢复，硬盘克隆，电子取证和提供操作系统（即LiveCD/DVDs）。</p><p>有很多不同的方法可以把ISO镜像挂载到Linux系统下。强大的mount 命令给我们提供了一个简单的解决方案。但是如果你需要很多工具来操作磁盘镜像，你可以试一试下面的这些强大的开源工具。</p><p>很多工具还没有看到最新的版本，所以如果你正在寻找一个很好用的开源工具，你也可以加入，一起来为开源做出一点贡献。</p><h3 id="furius-iso-mount" tabindex="-1">Furius ISO Mount <a class="header-anchor" href="#furius-iso-mount" aria-label="Permalink to “Furius ISO Mount”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-FuriusISOMountTool.png" alt=""></p><p>Furius ISO Mount是一个简单易用的开源应用程序，可以用来挂载镜像文件，它支持直接打开ISO,IMG,BIN,MDF和NRG格式的镜像而不用把他们烧录到磁盘。</p><p>特性：</p><ul><li>支持自动挂载ISO, IMG, BIN, MDF and NRG镜像文件</li><li>支持通过 loop 方式挂载 UDF 镜像</li><li>自动在根目录创建挂载点</li><li>自动解挂镜像文件</li><li>自动删除挂载目录，并返回到主目录之前的状态</li><li>自动记录最近10次挂载历史</li><li>支持挂载多个镜像文件</li><li>支持烧录ISO文件及IMG文件到光盘</li><li>支持MD5校验和SHA1校验</li><li>自动检索之前解挂的镜像</li><li>自动创建手动挂载和解挂的日志文件</li><li>语言支持（目前支持保加利亚语，中文（简体），捷克语，荷兰语，法语，德语，匈牙利语，意大利语，希腊语，日语，波兰语，葡萄牙语，俄语，斯洛文尼亚语，西班牙语，瑞典语和土耳其语）</li></ul><hr>',12)),i("ul",null,[i("li",null,[l[1]||(l[1]=t("项目网址： ",-1)),o(n,{href:"https://launchpad.net/furiusisomount/"},{default:s(()=>[...l[0]||(l[0]=[t("launchpad.net/furiusisomount/",-1)])]),_:1})]),l[2]||(l[2]=i("li",null,"开发者: Dean Harris (Marcus Furius)",-1)),l[3]||(l[3]=i("li",null,"许可： GNU GPL v3",-1)),l[4]||(l[4]=i("li",null,"版本号： 0.11.3.1",-1))]),l[37]||(l[37]=u('<p>###fuseiso</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-fuseiso.png" alt=""></p><p>fuseiso 是用来挂载ISO文件系统的一个开源的安全模块。</p><p>使用FUSE，我们完全可以在用户空间里运行一个完整的文件系统。</p><p>特性：</p><ul><li>支持读ISO,BIN和NRG镜像，包括ISO 9660文件系统</li><li>支持普通的ISO 9660级别1和级别2</li><li>支持一些常用的扩展，想Joliet，RockRidge和zisofs</li><li>支持非标准的镜像，包括CloneCD&#39;s IMGs 、Alcohol 120%&#39;s MDFs 因为他们的格式看起来恰好像BIN镜像一样</li></ul><hr>',7)),i("ul",null,[i("li",null,[l[6]||(l[6]=t("项目网址： ",-1)),o(n,{href:"http://sourceforge.net/projects/fuseiso/"},{default:s(()=>[...l[5]||(l[5]=[t("sourceforge.net/projects/fuseiso",-1)])]),_:1})]),l[7]||(l[7]=i("li",null,"开发者： Dmitry Morozhnikov",-1)),l[8]||(l[8]=i("li",null,"许可： GNU GPL v2",-1)),l[9]||(l[9]=i("li",null,"版本号： 20070708",-1))]),l[38]||(l[38]=i("p",null,"###iat",-1)),l[39]||(l[39]=i("p",null,[i("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-iat.png",alt:""})],-1)),l[40]||(l[40]=i("p",null,"iat（Iso 9660分析工具）是一个通用的开源工具，能够检测很多不同镜像格式文件的结构，包括BIN,MDF,PDI,CDI,NRG和B5I,并转化成ISO 9660格式.",-1)),l[41]||(l[41]=i("p",null,"特性：",-1)),l[42]||(l[42]=i("ul",null,[i("li",null,"支持读取（输入）NRG,MDF,PDI,CDI,BIN,CUE 和B5I镜像"),i("li",null,"支持用 cd 刻录机直接烧录光盘镜像"),i("li",null,"输出信息包括：进度条，块大小，ECC扇形分区（大小），头分区（大小），镜像偏移地址等等")],-1)),l[43]||(l[43]=i("hr",null,null,-1)),i("ul",null,[i("li",null,[l[11]||(l[11]=t("项目网址： ",-1)),o(n,{href:"http://sourceforge.net/projects/iat.berlios/"},{default:s(()=>[...l[10]||(l[10]=[t("sourceforge.net/projects/iat.berlios",-1)])]),_:1})]),l[12]||(l[12]=i("li",null,"开发者： Salvatore Santagati",-1)),l[13]||(l[13]=i("li",null,"许可： GNU GPL v2",-1)),l[14]||(l[14]=i("li",null,"版本号： 0.1.3",-1))]),l[44]||(l[44]=u('<p>###AcetoneISO</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-AcetoneISO.png" alt=""></p><p>AcetoneISO 是一个功能丰富的开源图形化应用程序，用来挂载和管理CD/DVD镜像。</p><p>当你打开这个程序，你就会看到一个图形化的文件管理器用来挂载镜像文件，包括专有的镜像格式，也包括像ISO, BIN, NRG, MDF, IMG 等等，并且允许您执行一系列的操作。</p><p>AcetoneISO是用QT 4写的，也就是说，对于基于QT的桌面环境能很好的兼容，像KDE，LXQT或是Razor-qt。</p><p>这个软件适用于所有正在寻找Linux版本的Daemon Tools的人。</p><p>特性：</p><ul><li>支持挂载大多数windows 镜像，界面简洁易用</li><li>可以将其所有支持镜像格式转换到ISO,或者是从中提取内容</li><li>加密，压缩，解压任何类型的镜像</li><li>转换DVD成xvid avi，支持将各种常规视频格式转换成xvid avi</li><li>从视频里提取声音</li><li>从不同格式中提取镜像中的文件，包括bin mdf nrg img daa dmg cdi b5i bwi pdi</li><li>用Kaffeine / VLC / SMplayer播放DVD镜像，可以从Amazon 自动下载封面。</li><li>从文件夹或者是CD/DVD生成ISO镜像</li><li>可以做镜像的MD5校验，或者是生成镜像的MD5校验码</li><li>计算镜像的ShaSums（128,256和384位）</li><li>支持加密，解密一个镜像文件</li><li>按兆数分拆和合并镜像</li><li>以高压缩比将镜像压缩成7z 格式</li><li>翻录PSX CD成BIN格式，以便在ePSXe/pSX模拟器里运行</li><li>为BIN和IMG格式恢复丢失的 CUE 文件</li><li>把MAC OS的DMG镜像转换成可挂载的镜像</li><li>从指定的文件夹中挂载镜像</li><li>创建数据库来管理一个大的镜像集合</li><li>从CD/DVD 或者是ISO镜像中提取启动文件</li><li>备份CD成BIN镜像</li><li>简单快速的把DVD翻录成Xvid AVI</li><li>简单快速的把常见的视频（avi, mpeg, mov, wmv, asf）转换成Xvid AVI</li><li>简单快速的把FLV 换换成AVI 格式</li><li>从YouTube和一些视频网站下载视频</li><li>提取一个有密码的RAR存档</li><li>支持转换任何的视频到PSP上</li><li>国际化的语言支持支持（英语，意大利语，波兰语，西班牙语，罗马尼亚语，匈牙利语，德语，捷克语和俄语）</li></ul><hr>',9)),i("ul",null,[i("li",null,[l[16]||(l[16]=t("项目网址: ",-1)),o(n,{href:"http://sourceforge.net/projects/acetoneiso/"},{default:s(()=>[...l[15]||(l[15]=[t("sourceforge.net/projects/acetoneiso",-1)])]),_:1})]),l[17]||(l[17]=i("li",null,"开发者: Marco Di Antonio",-1)),l[18]||(l[18]=i("li",null,"许可: GNU GPL v3",-1)),l[19]||(l[19]=i("li",null,"版本号: 2.3",-1))]),l[45]||(l[45]=u('<p>###ISO Master</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-ISOMaster.png" alt=""></p><p>ISO Master是一个开源、易用的、图形化CD 镜像编辑器，适用于Linux 和BSD 。可以从ISO 里提取文件，给ISO 里面添加文件，创建一个可引导的ISO，这些都是在一个可视化的用户界面完成的。可以打开ISO，NRG 和一些MDF文件，但是只能保存成ISO 格式。</p><p>ISO Master 是基于bkisofs 创建的，这是一个简单、稳定的阅读，修改和编写ISO 镜像的软件库，支持Joliet, RockRidge 和EL Torito扩展，</p><p>特性：</p><ul><li>支持读ISO 格式文件（ISO9660, Joliet, RockRidge 和 El Torito），大多数的NRG 格式文件和一些单轨道的MDF文件，但是，只能保存成ISO 格式</li><li>创建和修改一个CD/DVD 格式文件</li><li>支持CD 格式文件的添加或删除文件和目录</li><li>支持创建可引导的CD/DVD</li><li>国际化的支持</li></ul><hr>',7)),i("ul",null,[i("li",null,[l[21]||(l[21]=t("项目网址: ",-1)),o(n,{href:"http://www.littlesvr.ca/isomaster/"},{default:s(()=>[...l[20]||(l[20]=[t("www.littlesvr.ca/isomaster/",-1)])]),_:1})]),l[22]||(l[22]=i("li",null,"开发者: Andrew Smith",-1)),l[23]||(l[23]=i("li",null,"许可: GNU GPL v2",-1)),l[24]||(l[24]=i("li",null,"版本号: 1.3.11",-1))]),l[46]||(l[46]=i("hr",null,null,-1)),i("p",null,[l[26]||(l[26]=t("via: ",-1)),o(n,{href:"http://www.linuxlinks.com/article/20141025082352476/DiskImageTools.html"},{default:s(()=>[...l[25]||(l[25]=[t("http://www.linuxlinks.com/article/20141025082352476/DiskImageTools.html",-1)])]),_:1})]),i("p",null,[l[29]||(l[29]=t("作者：Frazer Kline 译者：",-1)),o(n,{href:"https://github.com/barney-ro"},{default:s(()=>[...l[27]||(l[27]=[t("barney-ro",-1)])]),_:1}),l[30]||(l[30]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...l[28]||(l[28]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[33]||(l[33]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...l[31]||(l[31]=[t("LCTT",-1)])]),_:1}),l[34]||(l[34]=t(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...l[32]||(l[32]=[t("Linux中国",-1)])]),_:1}),l[35]||(l[35]=t(" 荣誉推出",-1))])])}const g=r(D,[["render",S]]);export{O as __pageData,g as default};
